# פרק 1 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=1
TITLE='שיטות משפט בעולם והמשפחות המשפטיות'
SUM=[' <p>בעולם המערבי נהוג להבחין בין שתי <strong>"משפחות משפטיות"</strong> מרכזיות, שמהן נגזרות רוב שיטות המשפט המודרניות.</p> <h3>1.1 המשפט הקונטיננטלי (Civil Law)</h3> <p>שיטה שמקורה ב<strong>משפט הרומי</strong>, ומבוססת על <strong>קודיפיקציה</strong> — קובצי חוקים מקיפים וסדורים (כמו ה-Code Civil הצרפתי). תפקיד השופט הוא בעיקר <strong>ליישם</strong> את החוק הכתוב; לתקדים מעמד משני. נפוצה ביבשת אירופה.</p> <h3>1.2 המשפט המקובל (Common Law)</h3> <p>שיטה שמקורה ב<strong>אנגליה</strong>, שבה ה<strong>פסיקה</strong> היא מקור משפטי מרכזי. ההלכה נבנית "לבנה על לבנה" מתקדימים שיפוטיים, ולשופט תפקיד <strong>יוצר-הלכה</strong>. נפוצה באנגליה, ארה"ב, קנדה ואוסטרליה.</p> <h3>1.3 שיטות מעורבות</h3> <p>שיטות רבות (וישראל בכללן) משלבות יסודות משתי המשפחות.</p> <h3>1.4 נקודות מפתח למבחן</h3> <ul><li>קונטיננטלי — קודיפיקציה, השופט מיישם.</li><li>מקובל — תקדים, השופט יוצר הלכה.</li><li>ישראל — שיטה מעורבת.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('הערה', '', 'בשיעורי המבוא הדגש הוא תאורטי-השוואתי ולא על פסיקה קונקרטית. פסקי הדין המכוננים של השיטה הישראלית נלמדים בשיעור הבא, "המשפט הישראלי ומקורותיו".'), ('ע״א 191/51 סקורניק נ׳ סקורניק', 'דיון בשאלת תוקפם בישראל של נישואים שנערכו מחוץ לישראל, בשנותיה הראשונות של המדינה.', 'בית המשפט העליון הכיר בתוקפם של נישואים שנערכו בחו״ל לפי כללי המשפט הבינלאומי הפרטי, כשבני הזוג לא היו אזרחים או תושבים ישראלים בעת הנישואים והמדינה שבה נערכו הכירה בהם. פסק הדין ממחיש כיצד שיטה מעורבת מתמודדת עם מפגש בין דין אישי־דתי לבין שיטות זרות.'), ('בג״ץ 143/62 פונק־שלזינגר נ׳ שר הפנים', 'אישה נוצרייה, נתינת בלגיה, נישאה בקפריסין בנישואים אזרחיים ליהודי ישראלי וביקשה להירשם כנשואה במרשם האוכלוסין. פקיד הרישום סירב.', 'ברוב דעות נקבע שפקיד הרישום חייב לרשום כנשואים בני זוג שהציגו תעודת נישואים אזרחיים מחו״ל. תפקידו של פקיד הרישום הוא רישומי־סטטיסטי, ואין הוא מוסמך להכריע בתוקף הנישואים. ההלכה מדגימה את המתח בין הדין הדתי החל על נישואין בישראל לבין הכרה במעשים משפטיים אזרחיים שנעשו בשיטות זרות.'), ('בג״ץ 693/91 אפרת נ׳ הממונה על מרשם האוכלוסין במשרד הפנים', 'עתירה שבמסגרתה התבקש בית המשפט להכיר, בדרך עקיפה, במעמד של נישואים שלא נערכו לפי הדין הדתי.', 'בית המשפט סירב ליצור בפסיקה מוסד של נישואים אזרחיים בישראל, וקבע שהכרעה כזו נתונה למחוקק. פסק הדין משתייך לשורת פסקי דין שבהם בית המשפט שמר על המבנה שבו דיני הנישואין של כל עדה נקבעים לפי הדין הדתי שהוחל בחוק.'), ('בג״ץ 1000/92 בבלי נ׳ בית הדין הרבני הגדול', 'בני זוג התגרשו בבית הדין הרבני, שגם דן בחלוקת הרכוש ודחה את תביעת האישה למחצית הרכוש בטענה שהלכת השיתוף אינה חלה בבתי הדין הרבניים.', 'בג״ץ קבע שבתי הדין הדתיים, בדונם בעניינים ״אזרחיים״ נלווים שאינם ענייני מעמד אישי, חייבים להפעיל את המשפט האזרחי הכללי כפי שפירש אותו בית המשפט העליון — ובכלל זה חוק שיווי זכויות האישה והלכת השיתוף. זו הלכת יסוד על הגבול בין הרובד הדתי לרובד האזרחי בשיטה המעורבת הישראלית.')]
QS=[{'q': 'מהי ״משפחה משפטית״ במשפט המשווה?', 'o': ['כינוי לדיני המשפחה (נישואין, גירושין וירושה) בכל מדינה', 'קבוצה של שיטות משפט לאומיות בעלות מוצא היסטורי, מקורות ודרך חשיבה דומים', 'חוק בינלאומי המחייב מדינות לאמץ שיטת משפט מסוימת', 'רשימה רשמית של האו״ם שבה כל מדינה רשומה במשפחה אחת'], 'c': 1, 'e': 'נכון. משפחה משפטית היא כלי השוואתי המקבץ שיטות לפי דמיון במוצא, במקורות, בדרך החשיבה ובמוסדות.'}, {'q': 'אילו שני מבחנים הדגיש רנה דויד בסיווג שיטות משפט?', 'o': ['השיטה הכלכלית והדת הרשמית בלבד', 'הטכניקה המשפטית והאידיאולוגיה', 'גודל האוכלוסייה והשפה הרשמית', 'מספר השופטים ומספר הערכאות'], 'c': 1, 'e': 'נכון. דויד סיווג לפי הטכניקה (מושגים, מקורות, נימוק) ולפי האידיאולוגיה שעליה השיטה נשענת.'}, {'q': 'מהו ״הסגנון המשפטי״ לפי צווייגרט וקץ?', 'o': ['צירוף של חמישה גורמים: רקע היסטורי, דרך חשיבה, מוסדות ייחודיים, מקורות ואידיאולוגיה', 'אופן כתיבת פסקי הדין בלבד', 'מידת השימוש בשפה לטינית במשפט', 'דירוג המדינות לפי רמת שלטון החוק'], 'c': 0, 'e': 'נכון. צווייגרט וקץ קבעו את ״הסגנון״ לפי חמשת הגורמים האלה יחד.'}, {'q': 'מהו המקור הראשי של המשפט במשפחה הרומאנו־גרמנית?', 'o': ['חוות דעת של עורכי דין', 'פסקי דין של בית המשפט העליון כתקדים מחייב', 'מנהגי הקהילה', 'קודקס וחקיקה שיטתית'], 'c': 3, 'e': 'נכון. הקודקס — חיבור שיטתי ומקיף של עקרונות כלליים — הוא לב המשפט הקונטיננטלי.'}, {'q': 'סטודנט כותב: ״במשפט הקונטיננטלי השופטים אינם מפרסמים פסקי דין ואין לפסיקה כל השפעה״. מה הבעיה בטענה?', 'o': ['הטענה נכונה רק לגבי גרמניה', 'אין בעיה — זו טענה נכונה', 'במשפט הקונטיננטלי הפסיקה מחייבת יותר מהקודקס', 'בשיטות קונטיננטליות יש פסיקה רבה ומשפיעה; מה שאין הוא עיקרון פורמלי של תקדים מחייב'], 'c': 3, 'e': 'נכון. ההבדל מהמשפט המקובל הוא בהיעדר כלל פורמלי של stare decisis, לא בהיעדר פסיקה. ״פסיקה עקבית״ משפיעה מאוד בפועל.'}, {'q': 'מה מאפיין את המשפט המקובל יותר מכל דבר אחר?', 'o': ['היעדר חקיקה', 'כפיפות בתי המשפט למפלגה השלטת', 'קודקס אזרחי מקיף', 'תקדים מחייב והתפתחות המשפט ממקרה למקרה בפסיקה'], 'c': 3, 'e': 'נכון. עיקרון stare decisis וחשיבה מקרה־מקרה הם לב המשפט המקובל.'}, {'q': 'מה היה תפקידם ההיסטורי של ״דיני היושר״ (Equity) באנגליה?', 'o': ['להשלים ולתקן את נוקשות המשפט המקובל, ומהם צמחו מוסדות כמו הנאמנות וצו המניעה', 'לאכוף את המשפט הרומי באנגליה', 'לאפשר לכנסייה לשפוט בעניינים פליליים', 'להחליף את החקיקה של הפרלמנט'], 'c': 0, 'e': 'נכון. היושר התפתח כמערכת משלימה לתיקון תוצאות קשות של המשפט המקובל, והוריש מוסדות כמו Trust וצו מניעה.'}, {'q': 'מדינה ששפת המשפט בה היא אנגלית, יש בה קודקס אזרחי בסגנון צרפתי, אך המשפט הציבורי שלה מבוסס על מסורת המשפט המקובל. לאיזו קטגוריה היא קרובה ביותר?', 'o': ['משפט סוציאליסטי', 'משפט דתי', 'שיטה מעורבת, בדומה ללואיזיאנה או לקוויבק', 'משפט מקובל טהור'], 'c': 2, 'e': 'נכון. קודקס בסגנון צרפתי לצד משפט ציבורי ממסורת המשפט המקובל — זה בדיוק הדגם של לואיזיאנה וקוויבק.'}, {'q': 'מהם ארבעת המקורות הקלאסיים של המשפט המוסלמי?', 'o': ['תורה, משנה, תלמוד ושולחן ערוך', 'סונה, חקיקת פרלמנט, אמנות בינלאומיות ופסיקה', 'קוראן, סונה, איג׳מאע וקיאס', 'קוראן, קוד נפוליאון, פסיקה ומנהג'], 'c': 2, 'e': 'נכון. הקוראן, הסונה (מנהג הנביא), האיג׳מאע (הסכמת המלומדים) והקיאס (היקש).'}, {'q': 'במדינה מוסלמית מסוימת, דיני החוזים והנזיקין נקבעים בקודקס בסגנון צרפתי, ואילו נישואין, גירושין וירושה נידונים לפי השריעה. כיצד נכון לתאר אותה?', 'o': ['שיטה סוציאליסטית', 'שיטה דתית טהורה, כמו בכל מדינה מוסלמית', 'שיטה קונטיננטלית טהורה, כי יש קודקס', 'שיטה מעורבת — קונטיננטלית בעיקרה, עם משפט דתי במעמד האישי'], 'c': 3, 'e': 'נכון. זה דגם נפוץ: משפט כללי ממשפחה אחת, לצד דין דתי בענייני משפחה וירושה.'}, {'q': 'מה הייתה ״המג׳לה״?', 'o': ['אוסף פסקי דין של בית המשפט העליון הישראלי', 'חוקה בריטית לארץ ישראל', 'קודקס עות׳מאני של דיני ממונות מוסלמיים בסגנון קודקס אירופי, שבוטל בישראל ב־1984', 'אמנה בינלאומית לזכויות אדם'], 'c': 2, 'e': 'נכון. המג׳לה שילבה תוכן דתי־מוסלמי בצורה של קודקס, ובוטלה בחוק לביטול המג׳לה, התשמ״ד־1984.'}, {'q': 'מה אפיין את המשפט הסוציאליסטי, ומדוע יש שלא ראו בו משפחה נפרדת?', 'o': ['הוא היה מבוסס על השריעה', 'אידיאולוגיה מרקסיסטית־לניניסטית וקניין ציבורי, אך עם טכניקה של קודקסים קונטיננטליים', 'הוא לא כלל שום חקיקה כתובה', 'הוא נשען על תקדים מחייב כמו המשפט האנגלי'], 'c': 1, 'e': 'נכון. ההבדל היה בעיקר אידיאולוגי; הטכניקה נשארה קונטיננטלית, ולכן יש שראו בו ענף של המשפחה הרומאנו־גרמנית.'}, {'q': 'מהו ״השתלה משפטית״ (legal transplant)?', 'o': ['העברת כלל או מוסד משפטי משיטה אחת לשיטה אחרת', 'העברת שופט מערכאה לערכאה', 'ביטול חוק ישן והחלפתו בחוק חדש באותה מדינה', 'מינוי שופטים זרים לבית משפט לאומי'], 'c': 0, 'e': 'נכון. המונח, שטבע אלן ווטסון, מתאר אימוץ כללים ומוסדות משיטה זרה, כמו הקודקס השווייצרי בטורקיה.'}, {'q': 'מדוע הסיווג למשפחות משפטיות זכה לביקורת?', 'o': ['כי הוא אוסר על שימוש במשפט משווה', 'כי הוא מחייב מדינות לשנות את חוקיהן', 'כי הוא ממוקד באירופה, סטטי, ואינו משקף שיטות מעורבות ושינויים לאורך זמן', 'כי הוא נקבע באמנה שלא כל המדינות חתמו עליה'], 'c': 2, 'e': 'נכון. המבקרים טוענים שהסיווג הקלאסי מעמיד את אירופה במרכז, מתייחס למשפחות כקופסאות סגורות ואינו מתאים לשיטות משתנות ומעורבות.'}, {'q': 'לפי חוק שיפוט בתי דין רבניים (נישואין וגירושין), התשי״ג־1953, איך ייערכו נישואין וגירושין של יהודים בישראל?', 'o': ['על פי דין תורה', 'לפי חוק החוזים', 'לפי המשפט המקובל האנגלי', 'לפי בחירת בני הזוג'], 'c': 0, 'e': 'נכון. ס׳ 2 לחוק: ״נישואין וגירושין של יהודים ייערכו בישראל על פי דין תורה״.'}, {'q': 'מה מלמד ס׳ 1 לחוק שיפוט בתי דין רבניים (נישואין וגירושין) על מקור התוקף של הדין הדתי בישראל?', 'o': ['שהכנסת אינה יכולה לשנות את דיני הנישואין', 'שהדין הדתי חל בישראל מכוח עצמו, בלי קשר לחקיקה', 'שבתי הדין הרבניים כפופים לבית הדין השרעי', 'שהשיפוט הייחודי של בתי הדין הרבניים נובע מחוק של הכנסת, כלומר מהמחוקק החילוני'], 'c': 3, 'e': 'נכון. הסעיף מעניק לבתי הדין הרבניים שיפוט ייחודי בענייני נישואין וגירושין של יהודים — מכוח חוק המדינה.'}, {'q': 'בעניין בבלי, מה נקבע לגבי בתי הדין הדתיים?', 'o': ['שבדונם בעניינים ״אזרחיים״ נלווים הם חייבים להפעיל את המשפט האזרחי הכללי, כולל הלכת השיתוף', 'שהם רשאים לפסוק בענייני רכוש לפי ההלכה בלבד', 'שפסקי דינם אינם כפופים לביקורת בג״ץ', 'שאין להם סמכות לדון בגירושין'], 'c': 0, 'e': 'נכון. בג״ץ קבע שבעניינים אזרחיים שאינם מעמד אישי, בית הדין הדתי מחויב למשפט האזרחי הכללי כפי שפירש אותו בית המשפט העליון.'}, {'q': 'בעניין פונק־שלזינגר, מה הוטל על פקיד הרישום?', 'o': ['לבדוק אם הנישואים תקפים לפי דין תורה לפני הרישום', 'להעביר את ההכרעה לבית הדין הרבני', 'לרשום כנשואים בני זוג שהציגו תעודת נישואים אזרחיים מחו״ל, שכן תפקידו רישומי־סטטיסטי', 'לסרב לרשום כל נישואים שנערכו בחו״ל'], 'c': 2, 'e': 'נכון. פקיד הרישום אינו שופט; הוא רושם על סמך המסמך, והרישום אינו מכריע בשאלת תוקף הנישואים.'}, {'q': 'עותר מבקש מבג״ץ להכריז שזוגות בישראל רשאים להינשא בנישואים אזרחיים בתוך ישראל, משום שזה ״הוגן יותר״. לאור הפסיקה, מה הסיכוי?', 'o': ['נמוך — בית המשפט קבע שיצירת מוסד של נישואים אזרחיים היא עניין למחוקק', 'נמוך — כי לבג״ץ אין סמכות לדון בשום עניין של מעמד אישי', 'גבוה — ההלכה שנקבעה בעניין פונק־שלזינגר מחייבת זאת', 'גבוה — בית המשפט יוצר מוסדות משפטיים חדשים כדבר שבשגרה'], 'c': 0, 'e': 'נכון. בעניין אפרת ובפסקי דין נוספים בית המשפט סירב ליצור בפסיקה נישואים אזרחיים וקבע שזהו תפקיד המחוקק.'}, {'q': 'מה מתאר בצורה המדויקת ביותר את שיטת המשפט הישראלית?', 'o': ['שיטה דתית שבה ההלכה היא המקור העליון בכל התחומים', 'שיטה מעורבת: בסיס מנדטורי־אנגלי ותקדים מחייב, חקיקה מקורית בסגנון קונטיננטלי ודין דתי במעמד האישי', 'שיטת משפט מקובל טהורה כמו באנגליה, כולל חבר מושבעים', 'שיטה קונטיננטלית טהורה עם קודקס אזרחי שלם'], 'c': 1, 'e': 'נכון. זה התיאור המקובל של ישראל כשיטה מעורבת.'}, {'q': 'מהו המאפיין המרכזי של שיטת המשפט המקובל (Common Law)?', 'o': ['קודיפיקציה מקיפה', 'מעמד מרכזי לתקדים השיפוטי', 'היעדר בתי משפט', 'עליונות המשפט הדתי'], 'c': 1, 'e': 'ב-Common Law הפסיקה היא מקור משפטי מרכזי וההלכה נבנית מתקדימים.'}, {'q': 'כיצד מקובל לסווג את שיטת המשפט הישראלית?', 'o': ['קונטיננטלית טהורה', 'מקובלת טהורה', 'שיטה מעורבת', 'דתית בלבד'], 'c': 2, 'e': 'ישראל היא שיטה מעורבת — שילוב של תקדים אנגלו-אמריקאי, חקיקה קונטיננטלית ומשפט עברי.'}]
